insert into rules (key, value, unit, description)
values
  ('matching_tolerance_pct', 0.02, 'percent', 'Max variance between invoice and PO amount'),
  ('matching_tolerance_floor', 1000, 'INR', 'Minimum absolute tolerance, so small invoices aren''t over-policed'),
  ('auto_approve_limit', 200000, 'INR', 'Authority ceiling — above this a human approves regardless of match quality'),
  ('vendor_match_threshold', 0.85, 'score', 'Fuzzy name match score for confident vendor resolution'),
  ('vendor_match_floor', 0.6, 'score', 'Below this, vendor is treated as unknown'),
  ('po_ambiguity_margin', 0.15, 'score', 'Two PO candidates within this margin are ambiguous, never auto-picked'),
  ('near_duplicate_window_days', 14, 'days', 'Lookback window for near-duplicate detection'),
  ('split_pattern_window_days', 10, 'days', 'Window for threshold-splitting pattern detection'),
  ('split_pattern_min_invoices', 3, 'count', 'Minimum invoices against one PO to consider a split pattern'),
  ('stale_invoice_days', 180, 'days', 'Beyond this, invoice date is out of range');
insert into assumptions (text, category)
values
  ('Two-way match only — goods-receipt data unavailable, so quantity is checked against PO quantity rather than what was delivered', 'matching'),
  ('PO data is trusted; this process validates invoices against it, not the reverse', 'matching'),
  ('Vendor master is authoritative for bank details; changes to the master are out of scope', 'vendor'),
  ('Single currency per invoice; no FX conversion, so a currency mismatch holds rather than converting', 'currency'),
  ('Near-duplicate window of 14 days chosen to cover monthly billing without catching quarterly', 'matching'),
  ('Tolerance has both a percentage and an absolute floor, because 2% of a small invoice is tighter than any real AP team enforces', 'matching'),
  ('No authentication in scope; the demo uses permissive row-level security. Production would scope access per organisation', 'security');
